// Üretilen dosya: tool/ozgun/uret.py. Fizik · Elektrik ve manyetizma (zor).
const ozPhysics2Zor = <(String, String, List<String>, String)>[
  ('Bir öğrenci deneyde bir cismin yükünü 2,4 × 10⁻¹⁹ C olarak ölçtüğünü yazıyor. Bu sonuç için en doğru değerlendirme hangisidir? (e = 1,6 × 10⁻¹⁹ C)', 'Değer e\'nin tam katı olmadığı için ölçüm hatalıdır.', ['Değer 1,5 proton yüküne karşılık geldiği için deney sonucu doğrudur.', 'Cisim 2,4 elektron kazanmış demektir.', 'Bu yük ancak yalıtkanlarda görülür.'], '2,4 × 10⁻¹⁹ / 1,6 × 10⁻¹⁹ = 1,5 olup tam sayı değildir. Serbest bir cismin yükü e\'nin tam katı olmak zorunda olduğundan ölçüm hatalıdır.'),
  ('Kuarkların kesirli yükleri olmasına rağmen gündelik cisimlerin yükünün temel yükün tam katı çıkmasının nedeni nedir?', 'Kuarklar tek başına serbest bulunmaz, hep tam yüklü gruplar oluşturur.', ['Kuarkların yükü ölçülemeyecek kadar küçüktür.', 'Kuarklar yalnız nötronlarda bulunur.', 'Kuarkların yükleri zamanla elektronlara aktarılarak yok olur.'], 'Kuarklar hapsolmuştur; proton ve nötron gibi parçacıklarda birleşirler ve bu bileşik parçacıkların yükü e\'nin tam katıdır.'),
  ('Bir gama ışını fotonu, bir elektron ve bir pozitron çiftine dönüşebilir. Bu olay yükün korunumuyla nasıl bağdaşır?', 'Elektron −e, pozitron +e taşıdığından toplam yük yine sıfırdır.', ['Foton yükü pozitrona aktarır.', 'Olayda yük korunmaz; yalnız toplam enerji ve momentum korunur.', 'Oluşan çiftin toplam yükü +2e\'dir.'], 'Fotonun yükü sıfırdır; oluşan elektron ve pozitronun yükleri toplamı (−e) + (+e) = 0 olduğundan yük korunur.'),
  ('Yarıçapları r ve 2r olan iki metal küreden küçüğünün yükü +9q, büyüğü yüksüzdür. Küreler bir iletken telle bağlanırsa büyük kürenin son yükü ne olur?', '+6q', ['+3q', '+4,5q', '+9q'], 'Bağlantıda potansiyeller eşitlenir; yükler yarıçaplarla orantılı paylaşılır. 9q, 1:2 oranında bölünür: küçük +3q, büyük +6q alır.'),
  ('Bir metal içinde dış alan uygulanmamışken elektronlar hızla rastgele hareket ettiği hâlde net akımın sıfır olmasının nedeni nedir?', 'Rastgele hareketin her yöndeki katkıları birbirini dengeler.', ['Elektronlar aslında hareketsizdir.', 'Pozitif iyonlar elektronlarla aynı hızda aynı yönde hareket eder.', 'Elektronların yükü hareket sırasında sıfırlanır.'], 'Isıl hareket yön bakımından rastgeledir; belirli bir kesitten iki yönde geçen yük ortalamada eşittir, bu yüzden net akım sıfır olur.'),
  ('Elektroskop topuzuna yaklaştırılan cisim yaprakları biraz kapatıyor. Bu gözlem tek başına ele alındığında hangisi kesin olarak söylenebilir?', 'Cisim, elektroskobun yükünün işaretiyle aynı yükte değildir.', ['Cisim kesinlikle elektroskoba zıt işaretli yüklüdür.', 'Cisim kesinlikle yüksüzdür.', 'Cisim kesinlikle pozitif yüklüdür.'], 'Kapanma, zıt yüklü bir cisimle de yüksüz bir iletkenle de olabilir. Kesin olan yalnız cismin elektroskopla aynı işaretli yüklü olmadığıdır.'),
  ('Hidrojen atomunda proton ile elektron arasındaki elektriksel çekim, aralarındaki kütle çekimine göre nasıldır?', 'Yaklaşık 10³⁹ kat daha büyüktür.', ['Yaklaşık eşittir.', 'Kütle çekimi 10³⁹ kat daha büyüktür.', 'Elektriksel kuvvet yaklaşık 10 kat büyüktür.'], 'İkisi de uzaklığın karesiyle azaldığından oran uzaklıktan bağımsızdır; ke²/(Gmₚmₑ) ≈ 2 × 10³⁹ bulunur.'),
  ('Bir doğru üzerinde +q yükü x = 0\'da, +4q yükü x = 3 m\'de sabitlenmiştir. Üçüncü bir yükün dengede kalabileceği nokta x kaç metredir?', '1 m', ['2 m', '1,5 m', '−3 m'], 'Denge iki yükün arasında olur: q/x² = 4q/(3 − x)² ⇒ 3 − x = 2x ⇒ x = 1 m. Nokta küçük yüke daha yakındır.'),
  ('Bir kenarı a olan eşkenar üçgenin köşelerinde eşit büyüklükte +q, +q ve +q yükleri bulunuyor. Köşelerdeki bir yüke etki eden net kuvvetin büyüklüğü, iki yük arasındaki kuvvet F cinsinden nedir?', '√3·F', ['2√3·F', 'F', '3F'], 'Aralarında 60° bulunan iki eşit F kuvvetinin bileşkesi 2F·cos30° = √3·F\'dir.'),
  ('Aynı doğru üzerinde +9q yükü x = 0\'da, +q yükü x = 4 m\'de bulunuyor. İki yükün arasında net elektrik alanın sıfır olduğu nokta x kaç metredir?', '3 m', ['1 m', '2 m', '3,6 m'], '9q/x² = q/(4 − x)² ⇒ 3(4 − x) = x ⇒ x = 3 m. Alanın sıfır olduğu nokta küçük yüke yakındır.'),
  ('Alan çizgisi boyunca serbest bırakılan durgun bir pozitif yük hakkında hangisi her zaman doğrudur?', 'Başlangıçta ivmesi alan çizgisine teğettir.', ['Her zaman alan çizgisini tam olarak izleyerek ilerler, çizgiden hiç ayrılmaz.', 'Alan çizgisine dik doğrultuda hareket eder.', 'Hareketsiz kalır.'], 'Kuvvet ve ivme alanın yönündedir, yani çizgiye teğettir. Ancak çizgi eğriyse kazanılan hız nedeniyle parçacık çizgiden ayrılabilir.'),
  ('Eşit büyüklükte +q ve −q yüklerini birleştiren doğrunun orta noktasında potansiyel ve alan için hangisi doğrudur?', 'Potansiyel sıfır, alan sıfırdan farklıdır.', ['İkisi de sıfırdır.', 'Alan sıfırdır, potansiyel ise sıfırdan farklı ve pozitiftir.', 'İkisi de sıfırdan farklıdır.'], 'Potansiyel skalerdir: kq/d − kq/d = 0. Alanlar ise orada aynı yönü gösterir ve toplanır.'),
  ('Yüklü iletken bir kürenin merkezindeki potansiyel için hangisi doğrudur?', 'Kürenin yüzeyindeki potansiyele eşittir.', ['Sıfırdır.', 'Yüzeydeki potansiyelin iki katıdır, çünkü yük merkeze yakındır.', 'Sonsuz büyüktür.'], 'İletkenin içinde alan sıfır olduğundan noktalar arasında potansiyel farkı yoktur; içerideki her nokta yüzeyle aynı potansiyeldedir.'),
  ('Bir elektron, durgun hâlden başlayarak 100 V potansiyel farkı boyunca hızlandırılıyor. Elektronun son hızı yaklaşık kaç m/s\'dir? (mₑ = 9,1 × 10⁻³¹ kg, e = 1,6 × 10⁻¹⁹ C)', '5,9 × 10⁶ m/s', ['3,5 × 10¹³ m/s', '5,9 × 10⁴ m/s', '1,9 × 10⁷ m/s'], '½mv² = eV ⇒ v = √(2eV/m) = √(2 × 1,6 × 10⁻¹⁹ × 100 / 9,1 × 10⁻³¹) ≈ 5,9 × 10⁶ m/s.'),
  ('Negatif bir yük, alan çizgileri yönünde serbestçe değil de bir dış kuvvetle sabit hızla taşınıyor. Yükün elektriksel potansiyel enerjisi nasıl değişir?', 'Artar.', ['Azalır.', 'Değişmez.', 'Sıfıra iner.'], 'Alan yönünde ilerledikçe potansiyel azalır; negatif yük için U = qV olduğundan V azalırken U artar.'),
  ('Ardışık eş potansiyel yüzeyler arasındaki potansiyel farkı hep 10 V\'tur. Yüzeylerin birbirine çok sıklaştığı bölge için hangisi doğrudur?', 'Elektrik alan orada daha güçlüdür.', ['Elektrik alan orada sıfırdır.', 'Orada potansiyel en büyüktür.', 'Elektrik alan orada daha zayıftır.'], 'E ≈ ΔV/Δd ilişkisine göre aynı ΔV daha kısa uzaklıkta değişiyorsa alan daha büyüktür.'),
  ('Bir alfa parçacığı (yük +2e, kütle ~4mₚ) ve bir proton aynı potansiyel farkında durgun hâlden hızlandırılıyor. Kinetik enerjilerinin oranı (alfa/proton) nedir?', '2', ['1', '4', '1/2'], 'Kinetik enerji Eₖ = qV\'dir ve kütleye bağlı değildir; alfanın yükü 2 kat olduğundan enerjisi de 2 kattır.'),
  ('Paralel levhalar arasında bir yük, bir levhadan diğerine giderken kazandığı kinetik enerji neye bağlı değildir?', 'Levhalar arasındaki uzaklığa', ['Levhalar arasındaki potansiyel farkına', 'Yükün büyüklüğüne', 'Yükün işaretine ve yönüne'], 'Kazanılan enerji qV\'dir; V sabit tutulduğunda levhalar arası uzaklık alanı değiştirir ama toplam enerjiyi değiştirmez.'),
  ('Yalıtılmış, yüklü paralel levhalar (üreteçten ayrılmış) arasındaki uzaklık artırılırsa levhalar arasındaki potansiyel farkı nasıl değişir?', 'Artar.', ['Azalır.', 'Değişmez.', 'Sıfırlanır.'], 'Yalıtılmış levhalarda yük ve dolayısıyla alan sabit kalır; V = E·d olduğundan d artınca V artar.'),
  ('Üretece bağlı bir kondansatörün levhaları arasındaki uzaklık yarıya indirilirse depolanan enerji nasıl değişir?', 'İki katına çıkar.', ['Yarıya iner.', 'Dört katına çıkar.', 'Değişmez.'], 'V sabitken sığa iki katına çıkar; U = ½CV² olduğundan enerji de iki katına çıkar.'),
  ('Üreteçten ayrılmış yüklü bir kondansatörün levhaları arasındaki uzaklık iki katına çıkarılırsa depolanan enerji nasıl değişir?', 'İki katına çıkar.', ['Yarıya iner.', 'Değişmez.', 'Dörtte birine iner.'], 'Yük sabittir, sığa yarıya iner; U = q²/(2C) olduğundan enerji iki katına çıkar. Fark, levhaları ayırırken yapılan işten gelir.'),
  ('Bir kondansatörü 0\'dan V gerilimine yüklemek için yapılan iş neden qV değil de ½qV\'dir?', 'Yükleme sırasında gerilim 0\'dan V\'ye düzgün olarak artar.', ['Yükleme sırasında yükün yarısı ısı olarak kaybolur ve levhalara ulaşmaz.', 'Levhalardan yalnız biri yüklenir.', 'Enerjinin yarısı manyetik alanda depolanır.'], 'Her küçük yük, o anki gerilime karşı taşınır; gerilim doğrusal arttığından ortalama gerilim V/2 olur ve iş ½qV çıkar.'),
  ('Levha alanı 0,02 m², levhalar arası uzaklığı 1 mm olan hava aralıklı bir kondansatörün sığası yaklaşık kaçtır? (ε₀ = 8,85 × 10⁻¹² F/m)', '177 pF', ['17,7 pF', '1,77 nF', '8,85 pF'], 'C = ε₀A/d = 8,85 × 10⁻¹² × 0,02 / 0,001 = 1,77 × 10⁻¹⁰ F ≈ 177 pF.'),
  ('Özdeş dört kondansatörden ikisi seri, oluşan çift de kalan ikisine paralel bağlanıyor. Her birinin sığası C ise eşdeğer sığa nedir?', '2,5C', ['4C', '1,25C', '1,5C'], 'Seri çift C/2 eder; buna paralel iki C eklenir: C/2 + C + C = 2,5C.'),
  ('Yüklü bir kondansatör, yüksüz özdeş bir kondansatöre paralel bağlanıyor. Sistemin toplam enerjisi başlangıca göre nasıl olur?', 'Yarıya iner.', ['Değişmez.', 'İki katına çıkar.', 'Dörtte birine iner.'], 'Yük korunur, sığa 2C olur. U = q²/(2·2C) başlangıçtaki q²/(2C)\'nin yarısıdır; kayıp, bağlantıdaki akımla ısı ve ışımaya gider.'),
  ('Dielektrik bir maddenin kondansatörün sığasını artırmasının temel nedeni nedir?', 'Moleküllerin kutuplanıp içerdeki alanı zayıflatması', ['Dielektriğin serbest elektronlarla akım iletmesi', 'Levhalardaki yük miktarını kendiliğinden artırması', 'Levhalar arası uzaklığı kendiliğinden azaltması'], 'Kutuplanan moleküller dış alana zıt bir alan oluşturur; aynı yük için gerilim azalır ve C = q/V büyür.'),
  ('Bir kondansatörde levhalar arasına ince, dielektrik sabiti yüksek bir yalıtkan koymanın sığayı artırmanın yanında sağladığı başka bir yarar nedir?', 'Levhaların birbirine değmesini önleyip daha yüksek gerilime dayanmayı sağlar.', ['Kondansatörü iletkene dönüştürerek levhalar arasından geçen akımı artırır.', 'Levhalardaki yükü toprağa iletir.', 'Kondansatörün manyetik alan üretmesini sağlar.'], 'Katı dielektrik levhaları sabit ve çok yakın tutar; ayrıca havadan daha yüksek dielektrik dayanımı sayesinde delinme gerilimini yükseltir.'),
  ('Metal bir telde elektronların sürüklenme hızı saniyede milimetreler düzeyinde olduğu hâlde, anahtar kapanınca lambanın hemen yanmasının nedeni nedir?', 'Elektrik alan devre boyunca çok hızlı kurulur ve tüm elektronlar aynı anda harekete geçer.', ['Elektronlar anahtardan lambaya ışık hızına yakın bir hızla koşar ve hemen ulaşır.', 'Lamba önceden depolanmış yükle yanar.', 'Akım yalnız telin yüzeyinden geçer.'], 'Anahtar kapanınca alan teldeki bütün serbest elektronlara neredeyse ışık hızıyla ulaşır; lambanın içindeki elektronlar da hemen hareket etmeye başlar.'),
  ('Bir tel boyunca gerilerek uzunluğu iki katına çıkarılıyor; hacmi değişmiyor. Telin direnci nasıl değişir?', '4 katına çıkar.', ['İki katına çıkar.', 'Değişmez.', 'Yarıya iner.'], 'Hacim sabitken uzunluk 2 katına çıkınca kesit yarıya iner: R = ρ(2L)/(A/2) = 4R.'),
  ('Aynı maddeden yapılmış iki telden birinin uzunluğu ve çapı diğerinin iki katıdır. Kalın telin direncinin ince telinkine oranı nedir?', '1/2', ['1/√2', '1/4', '1'], 'Çap 2 kat olunca kesit 4 kat olur. R ∝ L/A ⇒ (2)/(4) = 1/2.'),
  ('Yarı iletkenlerin direnci sıcaklık arttıkça genellikle nasıl değişir ve neden?', 'Azalır; çünkü serbest kalan yük taşıyıcı sayısı artar.', ['Artar; çünkü ısınan iyonların titreşimleri elektronları daha çok engeller.', 'Değişmez; çünkü taşıyıcı sayısı sabittir.', 'Artar; çünkü elektronlar bağlanır.'], 'Yarı iletkenlerde ısı, bağlı elektronları serbest bırakır; taşıyıcı sayısındaki artış çarpışma etkisinden baskındır ve direnç düşer.'),
  ('Direnci renk bantlarıyla gösterilen bir dirençte bantların sırası kahverengi, siyah, kırmızıdır. Bu direncin değeri kaç ohmdur? (Kahverengi 1, siyah 0, kırmızı 2)', '1000 Ω', ['102 Ω', '10 200 Ω', '120 Ω'], 'İlk iki bant rakamları (1 ve 0), üçüncü bant çarpanı (10²) verir: 10 × 100 = 1000 Ω.'),
  ('Bir direncin uçlarındaki gerilim 3 katına çıkarıldığında akım 3 katına değil de daha az artıyor. Bu direnç için ne söylenebilir?', 'Ohmik değildir; direnci gerilimle artmaktadır.', ['Ohmiktir; çünkü akım gerilimle birlikte artmaktadır.', 'Direnci gerilimle azalmaktadır.', 'Ölçüm aletleri kesin olarak bozuktur.'], 'Ohmik dirençte akım gerilimle tam orantılıdır. Akım daha az arttığına göre V/I oranı, yani direnç, büyümüştür.'),
  ('Bir devrede 2 Ω\'luk direnç, paralel bağlı iki 6 Ω\'luk dirençle seri bağlanıp 15 V\'a bağlanıyor. 6 Ω\'luk dirençlerden birinden geçen akım kaç amperdir?', '1,5 A', ['3 A', '2,5 A', '0,75 A'], 'Paralel kısım 3 Ω; toplam 5 Ω, ana akım 3 A. Bu akım iki eş kola eşit bölünür: 1,5 A.'),
  ('Özdeş üç lambadan biri ana kolda, diğer ikisi birbirine paralel ve bu lambaya seri bağlıdır. Paralel lambalardan biri sökülürse ana koldaki lambanın parlaklığı nasıl değişir?', 'Azalır.', ['Artar.', 'Değişmez.', 'Lamba söner.'], 'Paralel kısmın direnci R/2\'den R\'ye çıkar; toplam direnç artar, ana akım azalır ve ana koldaki lamba sönükleşir.'),
  ('Bir köprü devresinde dört direnç P, Q, R, S biçiminde yerleştirilmiş ve P/Q = R/S koşulu sağlanmıştır. Ortadaki köprü kolundan geçen akım nedir?', 'Sıfır', ['Ana akımın yarısı', 'Ana akıma eşit', 'Ana akımın iki katı'], 'Wheatstone köprüsü dengedeyse köprü kolunun iki ucu aynı potansiyeldedir ve o koldan akım geçmez.'),
  ('Bir kenarı 1 Ω olan direnç telinden yapılmış kare çerçevenin karşılıklı iki köşesi arasındaki eşdeğer direnç kaç ohmdur?', '1 Ω', ['2 Ω', '4 Ω', '0,5 Ω'], 'Köşeler arasında her biri 2 Ω olan iki yol paralel bağlıdır: 2 × 2 / 4 = 1 Ω.'),
  ('Aynı kare çerçevede komşu iki köşe arasındaki eşdeğer direnç kaç ohmdur? (Her kenar 1 Ω)', '0,75 Ω', ['1,33 Ω', '0,375 Ω', '0,25 Ω'], 'Bir yol 1 Ω, diğer yol 3 Ω\'dur; paralel eşdeğer 1 × 3 / 4 = 0,75 Ω.'),
  ('Bir pilin uçlarına bağlı voltmetre, devre açıkken 9 V, pile 4 Ω\'luk direnç bağlıyken 8 V gösteriyor. Pilin iç direnci kaç ohmdur?', '0,5 Ω', ['1 Ω', '2 Ω', '0,25 Ω'], 'Dış dirençte I = 8/4 = 2 A. ε − V = I·r ⇒ 1 = 2r ⇒ r = 0,5 Ω.'),
  ('Emk\'sı 6 V, iç direnci 2 Ω olan bir üreteçten en büyük güç hangi dış dirençle çekilir?', '2 Ω', ['0 Ω', '6 Ω', 'Çok büyük bir dirençle'], 'Güç aktarımı, dış direnç iç dirence eşit olduğunda en büyüktür (R = r); bu durumda P = ε²/4r = 4,5 W olur.'),
  ('Eski bir pil ile yeni bir pilin emk\'ları aynı görünse de eski pilin cihazı çalıştıramamasının olası nedeni nedir?', 'Eski pilin iç direnci büyümüştür.', ['Eski pilin emk\'sı artmıştır.', 'Eski pilde yük kalmamış ama gerilim sıfıra inmiştir.', 'Eski pilin dış direnci sıfırlanmıştır.'], 'Kimyasal maddeler tükendikçe pilin iç direnci yükselir; açık devrede gerilim normal görünse de akım çekilince uç gerilimi düşer.'),
  ('Her birinin emk\'sı 2 V, iç direnci 0,5 Ω olan özdeş dört pil seri bağlanıp 6 Ω\'luk dirence bağlanıyor. Devreden geçen akım kaç amperdir?', '1 A', ['1,33 A', '0,5 A', '4 A'], 'Toplam emk 8 V, toplam iç direnç 2 Ω; I = 8/(6 + 2) = 1 A.'),
  ('İki paralel koldan oluşan bir devrede birinci kolda 6 V\'luk pil ve 2 Ω, ikinci kolda yalnız 4 Ω\'luk direnç vardır; kollar iki düğümde birleşir. İkinci koldaki akım kaç amperdir? (İç direnç yok)', '1 A', ['1,5 A', '3 A', '0,5 A'], 'Tek ilmek oluşur: 6 = I(2 + 4) ⇒ I = 1 A. Paralel görünse de pil ve dirençler tek bir yolu paylaşır.'),
  ('220 V\'luk 60 W ve 100 W\'lık iki lamba seri bağlanıp 220 V\'a bağlanırsa hangisi daha parlak yanar?', '60 W\'lık lamba', ['100 W\'lık lamba', 'İkisi eşit parlaklıkta', 'İkisi de hiç yanmaz'], 'Seride akım ortaktır ve P = I²R; direnci büyük olan 60 W\'lık lamba daha çok güç harcar ve daha parlak yanar.'),
  ('Bir galvanometreyi ampermetreye dönüştürmek için ne yapılır?', 'Galvanometreye paralel küçük bir direnç (şönt) bağlanır.', ['Galvanometreye seri olarak büyük değerli bir direnç bağlanır.', 'Galvanometrenin bobini çıkarılır.', 'Galvanometreye bir kondansatör eklenir.'], 'Şönt direnci akımın büyük bölümünü üzerinden geçirir; böylece galvanometre büyük akımları ölçebilir.'),
  ('Voltmetre yanlışlıkla bir lambaya seri bağlanırsa ne gözlenir?', 'Lamba yanmaz, voltmetre yaklaşık üreteç gerilimini gösterir.', ['Lamba normal parlaklıkta yanar, voltmetre ise sıfır değerini gösterir.', 'Voltmetre yanar ve kopar.', 'Lamba daha parlak yanar.'], 'Voltmetrenin çok büyük direnci akımı neredeyse sıfıra indirir; gerilimin hemen tamamı voltmetrenin uçlarına düşer.'),
  ('Kaçak akım rölesi hangi durumu algılayarak devreyi keser?', 'Faz ve nötr akımları arasında fark oluşmasını', ['Şebeke geriliminin 220 V\'un altına kısa süreliğine düşmesini', 'Aygıtın ısınmasını', 'Şebeke frekansının değişmesini'], 'Normalde faz ve nötr akımları eşittir; akımın bir kısmı insan ya da toprak üzerinden kaçarsa fark oluşur ve röle devreyi keser.'),
  ('Bir evde 16 A\'lik otomatik sigortanın bağlı olduğu hatta 2000 W ve 1800 W\'lık iki aygıt aynı anda çalıştırılıyor. Sigorta atar mı? (Gerilim 220 V)', 'Atar, çünkü toplam akım yaklaşık 17 A olur.', ['Atmaz, çünkü toplam akım yaklaşık 8 A olur.', 'Atmaz, çünkü güçler ayrı ayrı 16 A\'nin altındadır.', 'Atar, çünkü gerilim 380 V\'a çıkar.'], 'Toplam güç 3800 W; I = 3800/220 ≈ 17,3 A. Bu değer 16 A sınırını aştığından sigorta devreyi keser.'),
  ('Bir öğrenci elindeki iki çubuktan birinin mıknatıs, diğerinin sıradan demir olduğunu biliyor ama hangisi olduğunu bilmiyor. Başka araç kullanmadan nasıl ayırt edebilir?', 'Birinin ucunu ötekinin ortasına değdirip çekimi karşılaştırarak', ['İki çubuğu uç uca değdirip çekim olup olmadığına bakarak', 'Çubukları tartarak ve daha ağır olanın mıknatıs olduğunu kabul ederek', 'Çubukları suya bırakıp hangisinin batacağına bakarak'], 'Mıknatısın ortası zayıf çeker. A\'nın ucu B\'nin ortasını güçlü çekiyorsa A mıknatıstır; çekim zayıfsa mıknatıs B\'dir.'),
  ('Kayaçlardaki eski mıknatıslanma izleri Dünya\'nın manyetik alanı hakkında hangi bilgiyi vermiştir?', 'Manyetik kutupların geçmişte defalarca yer değiştirdiğini', ['Manyetik alanın hiç değişmediğini', 'Dünya\'nın çekirdeğinin katı olduğunu', 'Manyetik alanın Güneş\'ten geldiğini'], 'Okyanus tabanındaki bazaltlarda simetrik ters mıknatıslanma şeritleri bulunur; bu, manyetik kutupların tarih boyunca ters döndüğünü gösterir.'),
  ('Paramanyetik maddeler için hangisi doğrudur?', 'Dış alanda zayıfça mıknatıslanır, alan kalkınca mıknatıslığı kaybolur.', ['Dış alan olmadan da güçlü mıknatıstır.', 'Dış alana zıt yönde mıknatıslanır.', 'Hiçbir koşulda manyetik alandan etkilenmez.'], 'Paramanyetik maddelerde atomların kalıcı momentleri dış alanda kısmen hizalanır; alan kalkınca ısıl hareket düzeni bozar.'),
  ('Birbirine paralel iki uzun telden eşit ve zıt yönlü akımlar geçiyor. Tellerin tam ortasındaki noktada manyetik alan için ne söylenebilir?', 'Alanlar toplanır, sıfırdan farklıdır.', ['Alanlar birbirini yok eder, sıfırdır.', 'Yalnız birinci telin alanı etkilidir.', 'Alan tellere paralel olur.'], 'Sağ el kuralına göre zıt akımlı tellerin arada oluşturduğu alanlar aynı yöndedir ve toplanır. Aynı yönlü akımlarda ise ortada alan sıfır olurdu.'),
  ('Ampère yasası manyetik alanı neyle ilişkilendirir?', 'Kapalı bir yolun çevrelediği net akımla', ['Bir yüzeyden çıkan net elektrik yüküyle', 'Bir devredeki direnç ve gerilimle', 'Bir bobinin içindeki akının değişim hızıyla'], 'Ampère yasasına göre kapalı bir yol boyunca B·dl toplamı, yolun çevrelediği net akımla orantılıdır: ∮B·dl = μ₀I.'),
  ('Yarıçapı r olan tek sarımlı akım halkasının merkezindeki manyetik alanın büyüklüğü hangi ifadeyle verilir?', 'μ₀I/(2r)', ['μ₀I/(2πr)', 'μ₀nI', 'μ₀I·r/2'], 'Halkanın merkezinde B = μ₀I/(2r) olur; μ₀I/(2πr) ise düz telin alanını verir.'),
  ('Uzunluğu 0,5 m olan bir bobinde 1000 sarım var ve 2 A akım geçiyor. Bobin içindeki manyetik alan yaklaşık kaç tesladır? (μ₀ = 4π × 10⁻⁷ T·m/A)', '5 × 10⁻³ T', ['2,5 × 10⁻³ T', '1,3 × 10⁻³ T', '5 × 10⁻⁶ T'], 'B = μ₀(N/L)I = 4π × 10⁻⁷ × 2000 × 2 ≈ 5,03 × 10⁻³ T.'),
  ('Aynı hızla aynı manyetik alana dik giren bir proton ve bir elektron karşılaştırıldığında hangisi doğrudur?', 'Zıt yönlere sapar, elektronun yörüngesi çok daha küçüktür.', ['Aynı yöne sapar, yörüngeleri eşittir.', 'Zıt yönlere sapar, protonun yörüngesi çok daha küçüktür.', 'İkisi de sapmadan düz ilerler.'], 'Yükler zıt olduğundan kuvvetler zıttır; r = mv/(qB) ile kütlesi küçük elektronun yarıçapı yaklaşık 1836 kat küçüktür.'),
  ('Kütle spektrometresinde aynı hızla manyetik alana giren iyonların farklı yarıçaplı yörüngeler izlemesi hangi özelliklerinin farklı olmasından kaynaklanır?', 'Kütle/yük oranlarının', ['Renklerinin', 'Sıcaklıklarının', 'Elektron dizilimlerinin'], 'r = mv/(qB) olduğundan aynı v ve B için yarıçap m/q oranıyla orantılıdır; izotoplar bu yolla ayrılır.'),
  ('Alana dik giren yüklü bir parçacığın periyodunun hızdan bağımsız olduğu bilgisi hangi hızlandırıcının çalışma ilkesinin temelidir?', 'Siklotron', ['Van de Graaff üreteci', 'Doğrusal transformatör', 'Katot ışınlı tüp'], 'T = 2πm/(qB) hıza bağlı değildir; siklotronda parçacıklar hızlandıkça daha büyük yarım çemberler çizse de aynı frekansta hızlandırılır.'),
  ('Aralarında 0,1 m bulunan iki paralel uzun telden 5 A ve 4 A akımlar geçiyor. Tellerin birim uzunluğuna etki eden kuvvet kaç N/m\'dir? (μ₀ = 4π × 10⁻⁷ T·m/A)', '4 × 10⁻⁵ N/m', ['2 × 10⁻⁵ N/m', '4 × 10⁻⁷ N/m', '2 × 10⁻⁴ N/m'], 'F/L = μ₀I₁I₂/(2πd) = 2 × 10⁻⁷ × 5 × 4 / 0,1 = 4 × 10⁻⁵ N/m.'),
  ('Uzunluğu 0,2 m, kütlesi 0,02 kg olan yatay bir tel, yatay ve tele dik 0,5 T\'lık alanda havada asılı durabiliyor. Telden geçen akım kaç amperdir? (g = 10 m/s²)', '2 A', ['0,5 A', '4 A', '0,2 A'], 'Manyetik kuvvet ağırlığı dengeler: BIL = mg ⇒ I = 0,02 × 10 / (0,5 × 0,2) = 2 A.'),
  ('Amperin 2019 öncesindeki tanımı hangi olaya dayanıyordu?', 'Paralel iki akımlı tel arasındaki kuvvete', ['Bir pildeki kimyasal tepkimenin hızına', 'Bir lambanın yaydığı ışığın şiddetine', 'Bir kondansatörün dolma süresine'], 'Eski tanımda 1 m arayla duran iki paralel telden geçip metre başına 2 × 10⁻⁷ N kuvvet oluşturan akım 1 A kabul ediliyordu; 2019\'dan beri amper temel yüke dayanarak tanımlanır.'),
  ('Bir doğru akım motoru çalışırken bobinde üretilen ve uygulanan gerilime karşı koyan gerilime ne ad verilir?', 'Zıt emk', ['Hall gerilimi', 'Kısa devre gerilimi', 'Uç gerilimi'], 'Dönen bobinde indüksiyonla bir emk oluşur ve Lenz yasası gereği uygulanan gerilime karşı koyar; motor hızlandıkça zıt emk artar.'),
  ('Bir elektrikli matkap, delme sırasında sıkışıp dönemez hâle gelirse motor bobini çok çabuk ısınır. Bunun nedeni nedir?', 'Bobin dönmediği için zıt emk oluşmaz ve akım çok büyür.', ['Dönmeyen motorun direnci sıfırlanır ve gerilim artar.', 'Sıkışan uç bobine sürtünerek ısı verir.', 'Şebeke gerilimi motor durunca iki katına çıkar.'], 'Akım I = (V − ε_zıt)/R\'dir. Bobin durduğunda zıt emk sıfırlanır; akım yalnız bobin direnciyle sınırlanır ve çok yükselir.'),
  ('Manyetik alandaki dikdörtgen bir akım çerçevesine etki eden tork, çerçeve hangi konumdayken en büyüktür?', 'Çerçeve düzlemi alana paralelken', ['Çerçeve düzlemi alana dikken', 'Çerçeve alanla 30° açı yaparken', 'Çerçeve hangi konumda olursa olsun aynıdır'], 'Tork τ = NBIA·sinθ\'dir (θ: alan ile çerçeve normali arasındaki açı). Düzlem alana paralelken θ = 90° olur ve tork en büyüktür.'),
  ('Herhangi bir kapalı yüzeyden geçen net manyetik akının sıfır olması neyi gösterir?', 'Manyetik tek kutupların bulunmadığını', ['Manyetik alanın her yerde sıfır olduğunu', 'Manyetik alanın uzaklıkla değişmediğini', 'Kapalı yüzeyin içinde akım olmadığını'], 'Manyetizma için Gauss yasası: giren her alan çizgisi çıkar. Bu, yalıtılmış N ya da S kutbunun bulunmadığının ifadesidir.'),
  ('Bir bobinde indüklenen toplam yük miktarı, bobin direnci R ise neye bağlıdır?', 'Akıdaki toplam değişime', ['Akı değişiminin ne kadar hızlı olduğuna', 'Mıknatısın sıcaklığına', 'Galvanometrenin rengine'], 'q = I·Δt = (NΔΦ/(RΔt))·Δt = NΔΦ/R; geçen yük değişimin hızına değil toplam akı değişimine bağlıdır.'),
  ('Bazı trenlerde ve kamyonlarda kullanılan girdap akımlı frenlerin avantajı nedir?', 'Temas olmadan frenleme sağladıkları için aşınma azdır.', ['Fren sırasında enerji üreterek aracı hızlandırırlar.', 'Sabit hızla giden aracı da durdurabilecek en güçlü yöntemdirler.', 'Hiç ısı üretmezler.'], 'Hareketli metal disk ya da raydaki girdap akımları frenleme kuvveti oluşturur; sürtünme yüzeyi olmadığından aşınma yoktur. Etki hızla azalır, bu yüzden son duruş için başka fren gerekir.'),
  ('Alüminyum bir halka, akımı yeni açılan bir elektromıknatısın çekirdeği üzerine geçirilmişse halka havaya sıçrar. Bunun nedeni nedir?', 'Halkada indüklenen akımın alanı bobinin alanına zıttır ve itme oluşur.', ['Alüminyum ferromanyetik olduğu için güçlü çekilir.', 'Halka ısınıp genleşerek fırlar.', 'Bobin halkaya elektrik yükü aktarıp onu iter.'], 'Akım açılınca akı hızla artar; halkada zıt yönlü akım indüklenir ve iki zıt akım birbirini iter. Bu Elihu Thomson\'ın sıçrayan halka deneyidir.'),
  ('Bir uçağın kanatları Dünya\'nın manyetik alanında ilerlerken kanat uçları arasında küçük bir potansiyel farkı oluşur. Bu olay hangi kavramla açıklanır?', 'Hareketsel emk', ['Isıl iyonlaşma', 'Fotoelektrik olay', 'Kapasitif boşalma'], 'Metal kanat, Dünya\'nın alanının düşey bileşenini keserek hareket eden bir iletken çubuk gibi davranır; uçlar arasında BLv kadar emk oluşur.'),
  ('Raylar üzerinde kayan bir çubukla kurulu devrede çubuğu sabit hızla çekmeye devam etmek için neden sürekli kuvvet uygulamak gerekir?', 'Devreden geçen akım çubuğa harekete karşı bir manyetik kuvvet uygular.', ['Çubuğun kütlesi hareketle artar.', 'Manyetik alan çubuğu yere doğru çeker.', 'Çubuk hareket ettikçe rayın sürtünmesi sıfırlanır.'], 'İndüklenen akım BIL büyüklüğünde, hıza zıt bir kuvvet doğurur; bu kuvveti dengeleyen dış kuvvetin işi dirençte ısıya dönüşür.'),
  ('Büyük indüktanslı bir bobinin akımı anahtarla aniden kesildiğinde anahtar uçlarında kıvılcım görülmesinin nedeni nedir?', 'Akımın çok hızlı düşmesiyle büyük bir emk indüklenir.', ['Anahtarın metal kısmı erir ve sıçrar.', 'Bobin depoladığı yükü kondansatör gibi boşaltır.', 'Şebeke gerilimi anahtarda aniden yükselir.'], 'ε = L·ΔI/Δt; Δt çok küçük olunca emk binlerce volta ulaşabilir ve hava aralığında kıvılcım oluşturur.'),
  ('Arabalarda buji için gereken binlerce voltluk gerilim, 12 V\'luk aküden hangi yolla elde edilir?', 'Bir bobin devresindeki akımın aniden kesilmesiyle', ['Akünün hücrelerinin paralel bağlanmasıyla', 'Motordaki ısının elektriğe çevrilmesiyle', 'Bujinin bir kondansatör olarak dolmasıyla'], 'Ateşleme bobininde birincil akım aniden kesilir; hızlı akı değişimi çok sarımlı ikincil bobinde yüksek gerilim indükler.'),
  ('Dönen bir bobinin emk\'sı, bobin düzlemi hangi konumdayken en büyüktür?', 'Düzlem alan çizgilerine paralelken', ['Düzlem alan çizgilerine dikken', 'Bobin hareketsizken', 'Akı en büyük değerindeyken'], 'Düzlem alana paralelken akı sıfırdır ama en hızlı değiştiği andır; bu yüzden emk en büyüktür.'),
  ('Yalnız bir bobin içeren AC devresinde akım ile gerilim arasındaki faz ilişkisi nedir?', 'Akım, gerilimden çeyrek periyot geride kalır.', ['Akım ve gerilim aynı fazdadır.', 'Akım, gerilimden çeyrek periyot öndedir.', 'Akım ile gerilim arasında yarım periyot fark vardır.'], 'Bobin akım değişimine karşı koyduğundan akım gerilimin 90° gerisinden gelir; kondansatörde ise akım 90° öndedir.'),
  ('Bir AC devresinde ortalama güç neden P = V_etkin · I_etkin · cosφ biçiminde yazılır?', 'Akım ile gerilim arasındaki faz farkı gücü azaltır.', ['Etkin değerler her zaman tepe değerlerin iki katıdır.', 'cosφ terimi direncin sıcaklığa bağlılığını gösterir.', 'Alternatif akımda güç hiç harcanmaz.'], 'Faz farkı olduğunda bir periyodun bazı bölümlerinde enerji kaynağa geri döner; cosφ (güç katsayısı) gerçekte harcanan güç oranını verir.'),
  ('Transformatör çekirdeklerinin tek parça demir yerine ince ve birbirinden yalıtılmış saclardan yapılmasının amacı nedir?', 'Girdap akımı kayıplarını azaltmak', ['Çekirdeğin daha kolay mıknatıslanmasını engellemek', 'Bobinlerin sarım sayısını artırmak', 'Transformatörü daha ağır yapmak'], 'Yalıtılmış saclar girdap akımlarının dolaşabileceği yolu daraltır; böylece çekirdekte ısıya dönüşen enerji azalır.'),
  ('Bir transformatörün birincil bobinine 12 V\'luk bir akü bağlanıp ikincile bir lamba takılıyor. Lamba için ne gözlenir?', 'Akü bağlandığı anda kısa bir parlama dışında yanmaz.', ['Sürekli parlak yanar.', 'Akünün gerilimiyle orantılı sürekli yanar.', 'Sürekli titreyerek yanar.'], 'Yalnız bağlantı anında akım değişir ve kısa süreli bir emk indüklenir; ardından akım sabit kaldığı için ikincilde emk oluşmaz.'),
  ('Seri RLC devresinin rezonans frekansı hangi ifadeyle verilir?', 'f = 1/(2π√(LC))', ['f = 2π√(LC)', 'f = 1/(2πRC)', 'f = R/(2πL)'], 'X_L = X_C ⇒ 2πfL = 1/(2πfC) ⇒ f = 1/(2π√(LC)).'),
  ('Direnci 30 Ω, indüktif reaktansı 60 Ω, sığasal reaktansı 20 Ω olan seri bir devrenin empedansı kaç ohmdur?', '50 Ω', ['110 Ω', '70 Ω', '10 Ω'], 'Z = √(R² + (X_L − X_C)²) = √(900 + 1600) = 50 Ω.'),
  ('Seri RLC devresinde frekans rezonans frekansının çok altına indirilirse devrenin davranışına hangi eleman egemen olur?', 'Kondansatör', ['Bobin', 'Direnç', 'Üçü de eşit ölçüde etkili olur'], 'Düşük frekansta X_C = 1/(2πfC) çok büyür, X_L ise küçülür; devre sığasal karakter kazanır.'),
  ('İndüktansı 1 mH ve sığası 1 μF olan bir LC devresinin rezonans frekansı yaklaşık kaç hertzdir?', '5 kHz', ['500 Hz', '50 kHz', '159 Hz'], 'f = 1/(2π√(10⁻³ × 10⁻⁶)) = 1/(2π × 3,16 × 10⁻⁵) ≈ 5,03 × 10³ Hz.'),
  ('Bir iletim hattında gerilim 10 katına çıkarılırsa aynı güç iletilirken hattaki ısı kaybı nasıl değişir?', '100\'de birine iner.', ['10\'da birine iner.', '10 katına çıkar.', 'Değişmez.'], 'Akım 10\'da birine iner; kayıp I²R olduğundan 100\'de birine düşer.'),
  ('Germanyum ve silisyum gibi yarı iletkenler mutlak sıfıra yakın sıcaklıklarda nasıl davranır?', 'Yalıtkan gibi', ['Süper iletken gibi', 'Mıknatıs gibi', 'Metal gibi iyi iletken'], 'Çok düşük sıcaklıkta bağlardan kopacak ısıl enerji yoktur; serbest taşıyıcı kalmadığı için saf yarı iletken yalıtkan gibi davranır.'),
  ('Bir diyotun ileri yönde iletime geçmesi için silisyum diyotlarda uçlarına uygulanması gereken yaklaşık eşik gerilimi kaçtır?', '0,7 V', ['7 V', '0,07 V', '220 V'], 'Silisyum diyotlarda ileri yönde belirgin akım yaklaşık 0,6–0,7 V\'tan sonra başlar; germanyumda bu değer yaklaşık 0,3 V\'tur.'),
  ('Bir Faraday kafesinin içindeki aygıtların dışarıdaki elektrik alanlardan etkilenmemesinin nedeni nedir?', 'İletkendeki yükler, iç bölgede alanı sıfırlayacak biçimde dağılır.', ['Kafes içindeki havayı tamamen boşaltır.', 'Kafes, dış alanı ısıya çevirip yok eder.', 'Kafes, dış alanı iki katına çıkarıp yansıtır.'], 'Dış alan kafesteki serbest yükleri yeniden dağıtır; bu yükler içeride dış alanı tam olarak dengeleyen bir alan oluşturur.'),
  ('1 tesla aşağıdaki birim bileşimlerinden hangisine eşittir?', 'N/(A·m)', ['N·A/m', 'A/(N·m)', 'N·m/A'], 'F = BIL ⇒ B = F/(IL); birimi N/(A·m) olur.'),
  ('Elektrik akımını mekanik harekete çeviren ilk elektrik motoru düzeneğini 1821\'de gösteren ve bir mıknatıs çevresinde dönen tel deneyiyle tanınan bilim insanı kimdir?', 'Michael Faraday', ['Nikola Tesla', 'Thomas Edison', 'James Watt'], 'Faraday, cıva dolu kapta bir mıknatıs çevresinde dönen akımlı tel ile elektromanyetik dönme hareketini gösterdi.'),
  ('Ohm·farad (Ω·F) çarpımı hangi büyüklüğün birimini verir?', 'Zaman', ['Akım', 'Enerji', 'Güç'], 'Ω = V/A ve F = C/V; çarpım C/A = A·s/A = s olur. RC devrelerinde zaman sabiti τ = RC\'dir.'),
  ('Hall olayında, manyetik alana yerleştirilmiş akım taşıyan iletken bir şeritte ne gözlenir?', 'Şeridin iki kenarı arasında küçük bir gerilim oluşur.', ['Şeritteki akım kendiliğinden yön değiştirmeye başlar.', 'Şerit hemen süper iletken hâle geçer ve soğur.', 'Şeridin direnci sıfıra iner.'], 'Manyetik kuvvet yük taşıyıcıları şeridin bir kenarına iter; kenarlar arasında Hall gerilimi oluşur. Hall sensörleri manyetik alan ölçmede kullanılır.'),
  ('Uçakların kanat uçlarında görülen ince, sivri çubukların (statik boşaltıcılar) görevi nedir?', 'Uçuşta biriken yükü havaya yavaşça boşaltmak', ['Uçağın hızını ölçmek', 'Kanatlardaki buzu eritmek', 'Radyo yayınlarını güçlendirmek'], 'Hava sürtünmesiyle gövdede yük birikir; sivri uçlar yükü havaya sızdırarak radyo parazitini ve ani boşalmaları önler.'),
  ('Sivri uçlu iletkenlerde elektrik alanın çok güçlü olmasının sonucu olarak uçtan havaya yük kaçmasına ne ad verilir?', 'Korona boşalması', ['Fotoelektrik olay', 'Süper iletkenlik', 'Termoiyonik yayılım'], 'Sivri uçta alan havanın moleküllerini iyonlaştıracak kadar büyür; uçtan sürekli yük sızar ve bazen hafif bir ışıma görülür.'),
  ('Gauss yasası, kapalı bir yüzeyden geçen elektrik akısını neyle ilişkilendirir?', 'Yüzeyin içindeki net yükle', ['Yüzeyin dışındaki tüm yüklerin toplamıyla', 'Yüzeyin alanının karesiyle', 'Yüzeydeki manyetik alanın şiddetiyle'], 'Φ_E = Q_iç/ε₀; dışarıdaki yükler kapalı yüzeyden geçen net akıya katkı vermez.'),
  ('+5 μC\'lik bir nokta yükten 1 m uzaktaki A noktası ile 5 m uzaktaki B noktası arasındaki potansiyel farkı (V_A − V_B) kaç volttur? (k = 9 × 10⁹ N·m²/C²)', '36 000 V', ['45 000 V', '9 000 V', '180 000 V'], 'V_A = 45 000 V, V_B = 9 000 V; fark 36 000 V.'),
  ('Bir elektron, potansiyeli düşük bir noktadan yüksek bir noktaya serbestçe hareket ederse kinetik enerjisi nasıl değişir?', 'Artar.', ['Azalır.', 'Değişmez.', 'Önce azalır sonra sıfırlanır.'], 'Negatif yük için U = qV; V artarken elektronun potansiyel enerjisi azalır ve bu enerji kinetik enerjiye dönüşür.'),
  ('Yarıçapı 0,1 m olan iletken bir kürenin yüzeyindeki potansiyel 900 V\'tur. Kürenin yükü kaç coulombdur? (k = 9 × 10⁹ N·m²/C²)', '1 × 10⁻⁸ C', ['9 × 10⁻⁸ C', '1 × 10⁻⁷ C', '1,1 × 10⁻⁶ C'], 'V = kQ/R ⇒ Q = VR/k = 900 × 0,1 / 9 × 10⁹ = 1 × 10⁻⁸ C.'),
  ('Bir kondansatör R direnci üzerinden doldurulurken zaman sabiti τ = RC ne anlama gelir?', 'Yükün son değerinin yaklaşık %63\'üne ulaştığı süre', ['Kondansatörün tamamen dolduğu süre', 'Akımın iki katına çıktığı süre', 'Kondansatörün yarı yüküne ulaştığı süre'], 'Dolma q = Q(1 − e^(−t/RC)) ile olur; t = RC iken q ≈ 0,63Q\'dur. Tam dolma kuramsal olarak sonsuz sürer.'),
  ('Seri bağlı kondansatörlerden birinin sığası diğerlerinden çok küçükse eşdeğer sığa yaklaşık neye eşit olur?', 'En küçük sığaya', ['En büyük sığaya', 'Sığaların toplamına', 'Sığaların ortalamasına'], '1/C = Σ1/Cᵢ toplamında en küçük sığanın tersi baskındır; eşdeğer sığa ona yaklaşır ama ondan biraz küçük kalır.'),
  ('3 V\'luk bir LED, 9 V\'luk pille 20 mA akımla çalıştırılacaktır. LED\'e seri bağlanması gereken direnç kaç ohmdur?', '300 Ω', ['450 Ω', '150 Ω', '0,3 Ω'], 'Dirençte düşmesi gereken gerilim 9 − 3 = 6 V; R = 6 / 0,02 = 300 Ω.'),
  ('Bir kenarı R olan özdeş üç dirençten oluşan üçgenin iki köşesi arasındaki eşdeğer direnç nedir?', '2R/3', ['3R', 'R/3', '3R/2'], 'Köşeler arasında R ile 2R paralel bağlıdır: R × 2R / 3R = 2R/3.'),
  ('Özdeş dört dirençle elde edilebilecek en büyük ve en küçük eşdeğer dirençlerin oranı nedir?', '16', ['4', '8', '2'], 'Hepsi seride 4R, hepsi paralelde R/4 eder; oran 4R ÷ (R/4) = 16.'),
  ('İç direnci önemsiz olan bir akü ile iç direnci büyük bir pil aynı emk\'ya sahip. Hangisi bir marş motoru için daha uygundur ve neden?', 'Akü; çünkü büyük akımı gerilimi fazla düşürmeden verebilir.', ['Pil; çünkü iç direnci akımı güvenli biçimde sınırlar.', 'İkisi de aynı ölçüde uygundur; çünkü emk\'ları eşittir.', 'Pil; çünkü iç direnç enerjiyi depolar.'], 'Marş motoru çok büyük akım çeker; iç direnç büyükse I·r düşüşü uç gerilimini çökertir. Küçük iç dirençli akü bu iş için uygundur.'),
  ('Bir su ısıtıcısı 2 kg suyu 20 °C\'den 100 °C\'ye 7 dakikada ısıtıyor. Isı kaybı yoksa ısıtıcının gücü yaklaşık kaç watttır? (c = 4200 J/kg·°C)', '1600 W', ['672 W', '2240 W', '800 W'], 'Q = mcΔT = 2 × 4200 × 80 = 672 000 J; P = 672 000 / 420 s = 1600 W.'),
  ('Aynı ısıtıcı teli ikiye kesilip yalnız yarısı aynı prize bağlanırsa gücü nasıl değişir?', 'İki katına çıkar.', ['Yarıya iner.', 'Değişmez.', 'Dört katına çıkar.'], 'Direnç yarıya iner; gerilim sabitken P = V²/R olduğundan güç iki katına çıkar. Tel bu yüzden aşırı ısınabilir.'),
  ('Dünya yüzeyindeki manyetik alanın büyüklüğü yaklaşık hangi düzeydedir?', '25–65 mikrotesla', ['25–65 tesla', 'Yaklaşık 1 tesla', 'Yaklaşık 10⁻¹² tesla'], 'Dünya\'nın alanı ekvatorda yaklaşık 25–30 μT, kutuplarda yaklaşık 60–65 μT\'dır.'),
  ('Manyetik rezonans görüntüleme (MR) cihazlarında çok güçlü alan elde etmek için genellikle hangisi kullanılır?', 'Süper iletken bobinler', ['Büyük kalıcı demir mıknatıslar', 'Ferrit çekirdekli kondansatörler', 'Yüksek gerilimli paratonerler'], 'Süper iletken bobinler dirençsiz oldukları için çok büyük akımları ısı kaybı olmadan taşır ve birkaç teslalık alanlar üretir.'),
  ('Kuzey-güney doğrultusundaki bir telin hemen altında duran pusula, telden güneyden kuzeye akım geçince hangi yöne sapar?', 'İğnenin N ucu batıya doğru', ['İğnenin N ucu doğuya doğru', 'İğne hiç sapmaz', 'İğne düşey konuma geçer'], 'Sağ el kuralına göre telin altında alan batıyı gösterir (akım kuzeye, altta alan batıya); iğnenin N ucu batıya sapar. Ørsted\'in deneyi budur.'),
  ('Ev kablolarında faz ve nötr tellerinin yan yana aynı kılıfta taşınması manyetik alan açısından ne sağlar?', 'Zıt akımların alanları büyük ölçüde birbirini yok eder.', ['Alanlar toplanıp güçlü bir mıknatıs oluşur.', 'Kablo bir elektromıknatısa dönüşür.', 'Alan kablonun içinde hapsolup ısınır.'], 'Faz ve nötrden eşit ve zıt yönlü akımlar geçer; yakın tellerin alanları dışarıda neredeyse sıfıra iner.'),
  ('Alana eğik giren yüklü bir parçacığın yörüngesi hangi biçimdedir?', 'Sarmal', ['Düz çizgi', 'Parabol', 'Elips'], 'Hızın alana paralel bileşeni değişmez, dik bileşeni çember çizdirir; ikisinin birleşimi sarmal bir yörünge oluşturur.'),
  ('Hız seçici bir düzenekte, elektrik ve manyetik alanların birbirine dik olduğu bölgeden hangi hızdaki parçacıklar sapmadan geçer?', 'v = E/B', ['v = B/E', 'v = E·B', 'v = E²/B'], 'Elektrik kuvveti qE ile manyetik kuvvet qvB eşitlenince net kuvvet sıfır olur: v = E/B.'),
  ('Bir metal levha, iki mıknatıs kutbu arasında sarkaç gibi salınırken kısa sürede durur; levhada yarıklar açılırsa daha uzun salınır. Bunun nedeni nedir?', 'Yarıklar girdap akımlarının dolaşacağı yolları keser.', ['Yarıklar levhanın kütlesini artırır.', 'Yarıklar mıknatısın alanını güçlendirir.', 'Yarıklar havanın sürtünmesini sıfırlar.'], 'Girdap akımları hareketi frenler; yarıklar akımların büyük halkalar oluşturmasını engellediğinden frenleme etkisi azalır.'),
  ('Floresan lambaların eski tip balastlarında bobin kullanılmasının amacı nedir?', 'Yüksek gerilim darbesiyle lambayı yakmak ve akımı sınırlamak', ['Lambanın rengini değiştirmek', 'Lambayı doğru akımla çalıştırmak', 'Lambanın kütlesini dengelemek'], 'Starter açıldığında bobinde oluşan yüksek öz indüksiyon gerilimi gazı iyonlaştırır; ardından bobinin reaktansı akımı sınırlar.'),
  ('Alanı 0,05 m², sarım sayısı 100 olan bir bobin 0,2 T\'lık alanda 50 rad/s açısal hızla dönüyor. Üretilen emk\'nın en büyük değeri kaç volttur?', '50 V', ['5 V', '100 V', '500 V'], 'ε_max = NBAω = 100 × 0,2 × 0,05 × 50 = 50 V.'),
  ('Sığası 10 μF olan bir kondansatörün 50 Hz\'deki sığasal reaktansı yaklaşık kaç ohmdur?', '318 Ω', ['3,1 Ω', '31,8 Ω', '3180 Ω'], 'X_C = 1/(2πfC) = 1/(2π × 50 × 10⁻⁵) ≈ 318 Ω.'),
  ('Yalnız saf bir kondansatör içeren AC devresinde bir periyotta harcanan ortalama güç nedir?', 'Sıfır', ['V·I', 'V·I/2', 'I²·X_C'], 'Kondansatör yarım periyotta enerji alır, diğer yarıda geri verir; akım ve gerilim 90° faz farklı olduğundan cosφ = 0 ve ortalama güç sıfırdır.'),
  ('+q yükü ile −4q yükü arasında 30 cm vardır. Bu doğru üzerinde, üçüncü bir yüke net kuvvetin sıfır olduğu nokta nerededir?', '+q\'nun dışında, ondan 30 cm uzakta', ['İki yükün tam ortasında', '−4q\'nun dışında, ondan 30 cm uzakta', '+q\'dan 10 cm uzakta, yüklerin arasında'], 'Zıt yükler arasında kuvvetler aynı yöndedir, denge dışarıda ve küçük yük tarafında olur: q/x² = 4q/(x + 30)² ⇒ x = 30 cm.'),
  ('İki nokta yük arasındaki kuvvet, aralarına yağ gibi bir yalıtkan sıvı konunca neden azalır?', 'Sıvının molekülleri kutuplanarak yüklerin alanını zayıflatır.', ['Sıvı yüklerin bir kısmını yok eder.', 'Sıvı yükleri birbirinden uzaklaştırır.', 'Sıvı yüklerin işaretini değiştirir.'], 'Dielektrik ortamda kuvvet ε_r katı kadar azalır; kutuplanan moleküller her yükün çevresinde zıt yük katmanı oluşturur.'),
  ('Emk\'ları farklı iki pil paralel bağlanırsa ne sorun ortaya çıkar?', 'Büyük emk\'lı pil küçük olanı doldurmaya çalışır ve piller boşuna ısınır.', ['Toplam emk iki pilin toplamına eşit olur ve aygıt yanar.', 'İki pilden de akım geçmez ve devre çalışmaz.', 'Pillerin iç direnci sıfıra iner.'], 'Paralel bağlı farklı pillerin arasında bir iç akım dolaşır; bu akım enerji kaybına, ısınmaya ve pillerin bozulmasına yol açar.'),
  ('Evdeki elektrik tesisatında anahtarların ve sigortaların neden nötr yerine faz iletkenine bağlanması gerekir?', 'Anahtar kapalıyken aygıtın gerilimden tamamen ayrılması için', ['Faz iletkeninden akım geçmediği için', 'Nötr hattın gerilimi daha yüksek olduğu için', 'Faza bağlanınca aygıt daha az enerji harcadığı için'], 'Anahtar nötre bağlansaydı aygıt kapalıyken bile fazın gerilimi altında kalır ve dokunan kişi çarpılabilirdi.'),
  ('Bir proton ile bir elektron birbirinden uzaklaştırıldığında sistemin elektriksel potansiyel enerjisi nasıl değişir?', 'Artar.', ['Azalır.', 'Değişmez.', 'Sıfırdan küçük bir değerde sabit kalır.'], 'Zıt yükler için U = −k·e²/r negatiftir; r büyüdükçe U sıfıra yaklaşır, yani artar. Çekime karşı iş yapılmıştır.'),
  ('Potansiyeli 50 V olan bir eş potansiyel yüzeyden 20 V\'luk yüzeye giden +3 μC\'lik yük üzerinde elektrik kuvvetinin yaptığı iş kaç joule\'dür?', '9 × 10⁻⁵ J', ['2,1 × 10⁻⁴ J', '−9 × 10⁻⁵ J', '6 × 10⁻⁵ J'], 'W = q(V₁ − V₂) = 3 × 10⁻⁶ × 30 = 9 × 10⁻⁵ J; pozitif yük potansiyelin azaldığı yöne giderken alan pozitif iş yapar.'),
  ('Düzgün elektrik alana alana dik giren bir elektron, levhalar arasından çıkarken ilk hızına göre hızının büyüklüğü nasıl olur?', 'Daha büyüktür.', ['Daha küçüktür.', 'Aynıdır.', 'Sıfırdır.'], 'Alan doğrultusunda kazanılan hız bileşeni, sabit kalan dik bileşene eklenir; bileşke hız ilk hızdan büyüktür. Elektrik kuvveti iş yapar.'),
  ('Dielektrik sabiti (bağıl geçirgenlik) en büyük olan madde aşağıdakilerden hangisidir?', 'Saf su', ['Hava', 'Kâğıt', 'Cam'], 'Oda sıcaklığında suyun bağıl geçirgenliği yaklaşık 80\'dir; cam 4–10, kâğıt 2–4, hava yaklaşık 1\'dir.'),
  ('Yüksek gerilim hatlarında saf bakır yerine çelik özlü alüminyum kablolar kullanılmasının en önemli nedeni nedir?', 'Alüminyumun hafif ve ucuz olması, çeliğin dayanıklılık katması', ['Alüminyumun bakırdan daha iyi iletken olması', 'Çeliğin süper iletken olması', 'Alüminyumun hiç ısınmaması'], 'Alüminyumun özdirenci bakırdan biraz fazladır ama yoğunluğu çok düşüktür; uzun açıklıklı hatlarda ağırlık ve maliyet belirleyicidir.'),
  ('İç direnci 1000 Ω olan bir voltmetre, 1000 Ω\'luk bir dirence paralel bağlanıp ölçüm yapılıyor. Bu ölçüm için en doğru değerlendirme hangisidir?', 'Voltmetre devreyi belirgin biçimde değiştirir ve ölçüm güvenilmez olur.', ['Ölçüm hatasızdır, çünkü voltmetre paralel bağlanmıştır.', 'Voltmetre akımı ölçer ama gerilimi ölçemez.', 'Direncin değeri ölçüm sırasında iki katına çıkar.'], 'Voltmetre dirence paralel bağlanınca o kısmın eşdeğeri 500 Ω\'a düşer; devredeki gerilim dağılımı değişir. Voltmetrenin direnci ölçülen dirençten çok büyük olmalıdır.'),
  ('Bir pusula, yatay duran çubuk mıknatısın tam ortasının yanına konuyor. Pusulanın N ucu hangi yönü gösterir?', 'Mıknatısa paralel olarak mıknatısın S kutbu tarafını', ['Mıknatısa paralel olarak mıknatısın N kutbu tarafını', 'Mıknatısa dik olarak mıknatıstan uzağı', 'Mıknatısa dik olarak mıknatısın ortasını'], 'Mıknatısın dışında alan çizgileri N\'den S\'ye gider; ortanın yanında çizgiler mıknatısa paraleldir ve S kutbuna doğru yönelir. Pusulanın N ucu alan yönünü gösterir.'),
  ('Kenarı 10 cm olan kare bir çerçeve 0,5 T\'lık alana dik duruyor. Alan 0,2 saniyede yön değiştirip yine 0,5 T oluyor. Çerçevedeki akı değişiminin büyüklüğü kaç weberdir?', '1 × 10⁻² Wb', ['5 × 10⁻³ Wb', '0', '2,5 × 10⁻² Wb'], 'Φ = 0,5 × 0,01 = 5 × 10⁻³ Wb; yön değiştirince −5 × 10⁻³ Wb olur. |ΔΦ| = 1 × 10⁻² Wb.'),
  ('Raylar üzerindeki çubukla kurulu bir devrede çubuğun hızı iki katına çıkarılırsa devredeki dirençte harcanan güç nasıl değişir?', 'Dört katına çıkar.', ['İki katına çıkar.', 'Değişmez.', 'Yarıya iner.'], 'ε = BLv iki katına çıkar, akım da iki katına çıkar; P = ε²/R dört katına çıkar.'),
  ('Lenz yasası geçersiz olsaydı ve indüklenen akım akı değişimini destekleseydi ne olurdu?', 'Bir mıknatısa küçük bir itme, kendiliğinden hızlanan sonsuz enerjili bir hareket doğururdu.', ['İndüklenen akım her zaman sıfır olurdu.', 'Transformatörler daha verimsiz olurdu.', 'Mıknatıslar mıknatıslığını yitirirdi.'], 'Akımın değişimi desteklemesi, hareketi sürekli hızlandırırdı; bu, enerjinin korunumunu çiğneyen bir devridaim makinesi anlamına gelirdi.'),
  ('Bir LC devresinde sığa dört katına çıkarılırsa rezonans frekansı nasıl değişir?', 'Yarıya iner.', ['Dört katına çıkar.', 'Dörtte birine iner.', 'İki katına çıkar.'], 'f = 1/(2π√(LC)); C dört katına çıkınca √C iki katına çıkar ve frekans yarıya iner.'),
  ('Uzun mesafeli enerji iletiminde son yıllarda yüksek gerilimli doğru akım (HVDC) hatlarının da kullanılmasının bir nedeni nedir?', 'Çok uzun hatlarda ve deniz altı kablolarında reaktif kayıpların olmaması', ['Doğru akımın transformatörle kolayca yükseltilmesi', 'Doğru akımın hiç direnç görmemesi', 'HVDC hatlarının hiç yalıtım gerektirmemesi'], 'AC\'de kablo sığası ve indüktansı ek kayıp ve sınırlar getirir; çok uzun ya da deniz altı hatlarda HVDC daha verimli olabilir. Dönüşüm için elektronik çeviriciler kullanılır.'),
  ('Bir köprü doğrultucunun çıkışında dalgalanmayı azaltıp daha düzgün bir doğru gerilim elde etmek için çıkışa genellikle ne bağlanır?', 'Paralel bir kondansatör', ['Seri bağlı bir sigorta', 'Seri bir LED', 'Ters bağlı bir diyot'], 'Kondansatör gerilim tepelerinde dolar, aralarda boşalarak çıkışı besler; böylece dalgalı gerilim düzleşir.'),
  ('Grafitin, ametal bir element olmasına karşın elektriği iletmesinin nedeni nedir?', 'Katmanlarda serbestçe hareket edebilen elektronlar bulunması', ['Grafitin metal atomları içermesi', 'Grafitte iyonların akması', 'Grafitin süper iletken olması'], 'Grafitte her karbon üç komşusuna bağlanır; dördüncü elektron katman boyunca serbestçe dolaşır ve akımı iletir.'),
  ('Negatif yüklü bir elektroskobun topuzuna pozitif yüklü bir çubuk dokundurulursa ve çubuğun yükü elektroskobunkinden çok fazlaysa yapraklar nasıl davranır?', 'Önce kapanır, sonra pozitif yükle yeniden açılır.', ['Sürekli daha çok açılır.', 'Kapanır ve bir daha açılmaz.', 'Hiç değişmez.'], 'Önce elektroskobun negatif yükü nötrlenir ve yapraklar kapanır; fazla pozitif yük aktarılınca yapraklar pozitif yüklenip yeniden açılır.'),
  ('Aralarındaki uzaklık 1 m olan iki eşit nokta yük birbirini 0,9 N kuvvetle itiyor. Her bir yükün büyüklüğü kaç coulombdur? (k = 9 × 10⁹ N·m²/C²)', '1 × 10⁻⁵ C', ['1 × 10⁻¹⁰ C', '3 × 10⁻⁵ C', '1 × 10⁻⁴ C'], 'F = kq²/d² ⇒ q² = 0,9/(9 × 10⁹) = 10⁻¹⁰ ⇒ q = 10⁻⁵ C.'),
  ('Bir telde akım taşıyıcı elektronların ortalama sürüklenme hızı hangi değişiklikle artar? (Telin malzemesi ve akım sabit)', 'Telin kesitini küçültmekle', ['Telin kesitini büyütmekle', 'Telin uzunluğunu artırmakla', 'Teli bir yalıtkanla kaplamakla'], 'I = nqAv_d; aynı akım için kesit A küçülünce sürüklenme hızı v_d artmalıdır.'),
  ('Bir devrede iki düğüm arasında üç kol paralel bağlıdır: birinci kolda 12 V\'luk pil ile 2 Ω, ikinci kolda 6 Ω, üçüncü kolda 3 Ω vardır. Pilden çıkan akım kaç amperdir? (İç direnç yok)', '3 A', ['1,33 A', '2 A', '6 A'], '6 Ω ile 3 Ω paralel 2 Ω eder; pil koluyla birlikte toplam 4 Ω olur. I = 12/4 = 3 A; bu akım 6 Ω\'a 1 A, 3 Ω\'a 2 A olarak bölünür.'),
  ('Bir gerilim bölücüde 12 V\'luk kaynağa seri bağlı R₁ ve R₂ dirençleri vardır. R₂ uçlarından 3 V alınmak isteniyor ve R₂ = 1 kΩ\'dur. R₁ kaç kΩ olmalıdır?', '3 kΩ', ['4 kΩ', '0,33 kΩ', '1 kΩ'], 'V₂ = V·R₂/(R₁ + R₂) ⇒ 3 = 12 × 1/(R₁ + 1) ⇒ R₁ + 1 = 4 ⇒ R₁ = 3 kΩ.'),
  ('Aynı yönde akım taşıyan, aralarında 20 cm bulunan iki paralel telden 6 A ve 2 A akım geçiyor. Teller arasında manyetik alanın sıfır olduğu nokta 6 A\'lik telden kaç cm uzaktadır?', '15 cm', ['5 cm', '10 cm', '12 cm'], 'Aynı yönlü akımlarda alanlar arada zıttır: 6/x = 2/(20 − x) ⇒ 120 − 6x = 2x ⇒ x = 15 cm.'),
  ('Bir bobinin indüktansı sarım sayısıyla nasıl ilişkilidir? (Boyutlar ve çekirdek aynı)', 'Sarım sayısının karesiyle orantılıdır.', ['Sarım sayısıyla doğru orantılıdır.', 'Sarım sayısıyla ters orantılıdır.', 'Sarım sayısından bağımsızdır.'], 'Uzun bobinde L = μN²A/ℓ; sarım sayısı hem alanı hem akının geçtiği sarım sayısını artırdığı için etkisi karesel olur.'),
];
